CREATE OR REPLACE FUNCTION get_match_risk_profile(p_match_id text)
RETURNS jsonb AS $$
DECLARE
    result jsonb;
BEGIN
    SELECT jsonb_build_object(
        'Immun_Risk', riskmetrics->>'Immun_Risk',
        'Infect_Risk', riskmetrics->>'Infect_Risk',
        'Reject_Risk', riskmetrics->>'Reject_Risk',
        'Readmit_Risk', riskmetrics->>'Readmit_Risk',
        'Mort_Risk', riskmetrics->>'Mort_Risk'
    ) INTO result
    FROM risk_evaluation
    WHERE risk_eval_registry = p_match_id;

    RETURN result;
END;
$$ LANGUAGE plpgsql;

